          "passage": "사업시행자는 주거환경개선사업 및 재개발사업의 시행으로 철거되는 주택의 소유자 또는 세입자에게 해당 정비구역 안과 밖에 위치한 임대주택 등의 시설에 임시로 거주하게 하거나 주택자금의 융자를 알선하는 등 임시거주에 상응하는 조치를 하여야 한다.\n\n[지문 ②]\n사업시행자는 순환용주택에 거주하는 자가 정비사업이 완료된 후에도 순환용주택에 계속 거주하기를 말하는 때에는 대통령령으로 정하는 바에 따라 매각하거나 임대할 수 있다. 이 경우 사업시행자가 소유하는 순환용주택은 법 제74조에 따라 인가받은 관리처분계획에 따라 토지등소유자에게 처분된 것으로 본다.",
